/**
 * Central media configuration shared by the browser and the server.
 *
 * Feed media lives in the existing public `posts` bucket. Paths follow the current
 * `posts/<uid>/...` convention so Storage RLS keeps working unchanged:
 *
 *   posts/<uid>/feed-media/<mediaId>/original.<ext>
 *   posts/<uid>/feed-media/<mediaId>/variants/feed-960.webp
 *
 * Anything under `feed-media/` is generated by the Kith media pipeline; other `posts/`
 * paths remain legacy uploads and continue to render as-is.
 */

export const FEED_MEDIA_BUCKET = 'posts';

/** Folder inside the existing bucket, below the uploader's uid. */
export const FEED_MEDIA_FOLDER = 'feed-media';

export const FEED_MEDIA_LIMITS = {
  /** A post can show at most four images. Videos keep their existing behaviour. */
  maxImagesPerPost: 4,
  maxImageBytes: 10 * 1024 * 1024,
  maxTotalImageBytesPerPost: 30 * 1024 * 1024,
  maxDimension: 12_000,
  minDimension: 32,
} as const;

export type FeedMediaStatus = 'pending' | 'processing' | 'ready' | 'failed';

export const FEED_MEDIA_STATUSES: readonly FeedMediaStatus[] = [
  'pending',
  'processing',
  'ready',
  'failed',
];

export type FeedVariantName = 'thumbnail' | 'feed-640' | 'feed-960' | 'feed-1600';

export interface FeedVariantSpec {
  name: FeedVariantName;
  /** Fit inside a square of this size without cropping or upscaling. */
  maxWidth: number;
  maxHeight: number;
  quality: number;
}

/** Pre-generated variants used for the four common feed widths. */
export const FEED_MEDIA_VARIANTS: readonly FeedVariantSpec[] = [
  { name: 'thumbnail', maxWidth: 320, maxHeight: 320, quality: 72 },
  { name: 'feed-640', maxWidth: 640, maxHeight: 640, quality: 78 },
  { name: 'feed-960', maxWidth: 960, maxHeight: 960, quality: 80 },
  { name: 'feed-1600', maxWidth: 1600, maxHeight: 1600, quality: 82 },
] as const;

/** Formats the pipeline accepts. SVG is deliberately excluded (vector/script surface). */
export const FEED_MEDIA_ALLOWED_MIME = [
  'image/jpeg',
  'image/png',
  'image/webp',
  'image/gif',
  'image/avif',
] as const;

export type FeedMediaMime = (typeof FEED_MEDIA_ALLOWED_MIME)[number];

export const FEED_MEDIA_MIME_BY_FORMAT: Record<string, FeedMediaMime> = {
  jpeg: 'image/jpeg',
  png: 'image/png',
  webp: 'image/webp',
  gif: 'image/gif',
  avif: 'image/avif',
};

export const FEED_MEDIA_FORMAT_BY_MIME: Record<FeedMediaMime, string> = {
  'image/jpeg': 'jpeg',
  'image/png': 'png',
  'image/webp': 'webp',
  'image/gif': 'gif',
  'image/avif': 'avif',
};

/** File extension used in the immutable original path for each accepted format. */
export const FEED_MEDIA_EXTENSION_BY_MIME: Record<FeedMediaMime, string> = {
  'image/jpeg': 'jpg',
  'image/png': 'png',
  'image/webp': 'webp',
  'image/gif': 'gif',
  'image/avif': 'avif',
};

export const FEED_MEDIA_EXTENSIONS = ['jpg', 'jpeg', 'png', 'webp', 'gif', 'avif'] as const;

export function isAllowedFeedMime(value: string | null | undefined): value is FeedMediaMime {
  return !!value && (FEED_MEDIA_ALLOWED_MIME as readonly string[]).includes(value);
}

export function feedMediaOriginalPath(userId: string, mediaId: string, extension: string): string {
  return `${userId}/${FEED_MEDIA_FOLDER}/${mediaId}/original.${extension}`;
}

export function feedMediaVariantsFolder(userId: string, mediaId: string): string {
  return `${userId}/${FEED_MEDIA_FOLDER}/${mediaId}/variants`;
}

export function feedMediaVariantPath(
  userId: string,
  mediaId: string,
  variant: FeedVariantName,
): string {
  return `${feedMediaVariantsFolder(userId, mediaId)}/${variant}.webp`;
}

/**
 * Which variants are worth generating for an image. Sharp is also told not to enlarge,
 * but planning here keeps unnecessary work (and metadata rows) out of the pipeline.
 */
export function planFeedVariants(
  width: number,
  height: number,
): readonly FeedVariantSpec[] {
  if (!Number.isFinite(width) || !Number.isFinite(height) || width <= 0 || height <= 0) return [];
  return FEED_MEDIA_VARIANTS.filter(
    (spec) => width > spec.maxWidth || height > spec.maxHeight,
  );
}

/** True for the canonical media path shape this pipeline is allowed to read. */
export function isFeedMediaOriginalPath(
  userId: string,
  mediaId: string,
  path: string,
): boolean {
  const escapedUser = userId.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const escapedId = mediaId.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const pattern = new RegExp(
    `^${escapedUser}/${FEED_MEDIA_FOLDER}/${escapedId}/original\\.(${FEED_MEDIA_EXTENSIONS.join('|')})$`,
  );
  return pattern.test(path);
}

/** UUID v4-ish ids keep storage paths and database keys opaque and collision-free. */
export const FEED_MEDIA_ID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function isFeedMediaId(value: unknown): value is string {
  return typeof value === 'string' && FEED_MEDIA_ID_RE.test(value);
}
